db = sqlite3.connect(":memory:")
db.execute("CREATE TABLE produk (id INTEGER PRIMARY KEY, nama TEXT, harga INT, stok INT)")
db.executemany("INSERT INTO produk (nama, harga, stok) VALUES (?, ?, ?)",
